from datetime import date, timedelta
from collections import defaultdict


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays is not None else set()
        # Maps employee -> year -> used_days
        self.used_leave: dict[str, dict[int, int]] = defaultdict(lambda: defaultdict(int))

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        if end < start:
            raise ValueError("End date cannot be before start date.")

        if (start - today).days < 3:
            raise ValueError("Leave request must be made at least 3 days before start date.")

        # Calculate leave days requested per year
        days_per_calendar_year: dict[int, int] = defaultdict(int)
        curr = start
        one_day = timedelta(days=1)
        while curr <= end:
            # 0-4 are Monday-Friday, 5-6 are Saturday-Sunday
            if curr.weekday() < 5 and curr not in self.holidays:
                days_per_calendar_year[curr.year] += 1
            curr += one_day

        # Check if the employee has enough remaining days in each involved year
        for year, needed in days_per_calendar_year.items():
            if needed > self.remaining(employee, year):
                raise ValueError(
                    f"Insufficient remaining leave days in {year}: needed {needed}, "
                    f"available {self.remaining(employee, year)}."
                )

        # Deduct leave days
        total_used = 0
        for year, needed in days_per_calendar_year.items():
            self.used_leave[employee][year] += needed
            total_used += needed

        return total_used

    def remaining(self, employee: str, year: int) -> int:
        used = self.used_leave[employee][year]
        return max(0, self.days_per_year - used)
